#!/bin/sh
# Generated by FWShift: rows for the packet filter (and NAT) of a Phoenix Contact mGuard, added with gaiconfig.
# Read the report first: what is not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE            prints the gaiconfig calls; runs anywhere
#   sh THIS_FILE                      on the mGuard (SSH, as root or admin): adds the groups and rows
#   FWSHIFT_APPEND=yes sh THIS_FILE   also when the tables have rows: the new ones go after them
#
# Nothing is changed or deleted, and no interface, route or access to the mGuard is touched. Every call but the last
# writes with --silent; the last one reconfigures, and the rows take effect then. A call gaiconfig refuses stops the
# script: what was written before is stored but not active (the groups start with 'fws_', the rows' comments
# with the names of the rules); remove it in the web interface, or run the script again after fixing the cause.
set -u
DRY_RUN="${DRY_RUN:-}"
FWSHIFT_APPEND="${FWSHIFT_APPEND:-}"
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
gc() {
  if [ -n "$DRY_RUN" ]; then printf 'gaiconfig' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; return 0; fi
  gaiconfig "$@" >/dev/null || fail "gaiconfig $*"
}
rows() {
  if [ -n "$DRY_RUN" ]; then echo 0; return 0; fi
  gaiconfig --get-rowcount "$1" || fail "gaiconfig --get-rowcount $1"
}
named() {
  [ -z "$DRY_RUN" ] && gaiconfig --get "$1" 2>/dev/null | grep -F -q "NAME = \"$2\""
}
if [ -z "$DRY_RUN" ] && ! command -v gaiconfig >/dev/null 2>&1; then fail "gaiconfig not found: run this on the mGuard"; fi
for t in FW_INCOMING FW_OUTGOING FW_INCOMING_WAN_DMZ FW_INCOMING_DMZ_LAN FW_OUTGOING_LANDMZ FW_1TO1_NAT FW_NAT; do
  n=$(rows "$t")
  if [ "$n" != 0 ] && [ "$FWSHIFT_APPEND" != yes ]; then
    fail "$t has $n rows, which the mGuard would check before the new ones; nothing was written (FWSHIFT_APPEND=yes adds after them)"
  fi
done
named FW_GROUP_IP fws_blocked-nets && fail 'an IP group named fws_blocked-nets exists; nothing was written'
named FW_GROUP_PORT fws_web-in && fail 'a port group named fws_web-in exists; nothing was written'
named FW_GROUP_IP fws_web-in_dst && fail 'an IP group named fws_web-in_dst exists; nothing was written'
named FW_GROUP_IP fws_mail-server && fail 'an IP group named fws_mail-server exists; nothing was written'
named FW_GROUP_PORT fws_office-out && fail 'a port group named fws_office-out exists; nothing was written'
named FW_GROUP_PORT fws_office-out_2 && fail 'a port group named fws_office-out_2 exists; nothing was written'
named FW_GROUP_IP fws_office-out_src && fail 'an IP group named fws_office-out_src exists; nothing was written'
named FW_GROUP_PORT fws_office-dmz && fail 'a port group named fws_office-dmz exists; nothing was written'
named FW_GROUP_IP fws_office-lan && fail 'an IP group named fws_office-lan exists; nothing was written'
named FW_GROUP_IP fws_dmz-servers && fail 'an IP group named fws_dmz-servers exists; nothing was written'
named FW_GROUP_IP fws_admin-hosts && fail 'an IP group named fws_admin-hosts exists; nothing was written'
named FW_GROUP_PORT fws_lab-all && fail 'a port group named fws_lab-all exists; nothing was written'
named FW_GROUP_IP fws_lab-net && fail 'an IP group named fws_lab-net exists; nothing was written'

# FW_GROUP_IP
N=$(rows FW_GROUP_IP)
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_blocked-nets --set .COMMENT 'FWShift: blocked-nets'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 198.51.100.0/24
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_web-in_dst --set .COMMENT 'FWShift: web-servers, 203.0.113.3'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.20.0.10/31
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 203.0.113.3
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_mail-server --set .COMMENT 'FWShift: mail-server'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.20.0.25
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_office-out_src --set .COMMENT 'FWShift: 10.10.0.0-10.10.0.199, 10.10.0.221-10.10.0.255, 2001:db8:10::/64'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.10.0.0-10.10.0.199
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.10.0.221-10.10.0.255
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_office-lan --set .COMMENT 'FWShift: office-lan'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.10.0.0/24
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_dmz-servers --set .COMMENT 'FWShift: dmz-servers'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.20.0.10/31
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.20.0.25
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_admin-hosts --set .COMMENT 'FWShift: admin-hosts'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.10.0.50/31
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_lab-net --set .COMMENT 'FWShift: lab-net'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.30.0.0/24
N=$((N+1))

# FW_GROUP_PORT
N=$(rows FW_GROUP_PORT)
gc --silent --goto FW_GROUP_PORT --add-row --set .NAME fws_web-in --set .COMMENT 'FWShift: web-in'
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 80
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 443
N=$((N+1))
gc --silent --goto FW_GROUP_PORT --add-row --set .NAME fws_office-out --set .COMMENT 'FWShift: office-out'
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 53
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 80
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 443
N=$((N+1))
gc --silent --goto FW_GROUP_PORT --add-row --set .NAME fws_office-out_2 --set .COMMENT 'FWShift: office-out'
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 53
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 123
N=$((N+1))
gc --silent --goto FW_GROUP_PORT --add-row --set .NAME fws_office-dmz --set .COMMENT 'FWShift: office-dmz'
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 25
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 80
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 443
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 8080
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 8443
N=$((N+1))
gc --silent --goto FW_GROUP_PORT --add-row --set .NAME fws_lab-all --set .COMMENT 'FWShift: lab-all'
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 5000-5010
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 8080
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 8443
N=$((N+1))

# FW_INCOMING
N=$(rows FW_INCOMING)
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF ext1 --set .PROTO all --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF DROP --set .LOG no --set .COMMENT block-bad-nets
gc --silent --set-refname "FW_INCOMING.$N.FROM_IP" fws_blocked-nets
N=$((N+1))

# FW_OUTGOING
N=$(rows FW_OUTGOING)
gc --silent --goto FW_OUTGOING --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT 0 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT office-out
gc --silent --set-refname "FW_OUTGOING.$N.FROM_IP" fws_office-out_src
gc --silent --set-refname "FW_OUTGOING.$N.IN_PORT" fws_office-out
N=$((N+1))
gc --silent --goto FW_OUTGOING --add-row --set .PROTO udp --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT 0 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT office-out
gc --silent --set-refname "FW_OUTGOING.$N.FROM_IP" fws_office-out_src
gc --silent --set-refname "FW_OUTGOING.$N.IN_PORT" fws_office-out_2
N=$((N+1))

# FW_INCOMING_WAN_DMZ
N=$(rows FW_INCOMING_WAN_DMZ)
gc --silent --goto FW_INCOMING_WAN_DMZ --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF DROP --set .LOG no --set .COMMENT block-bad-nets
gc --silent --set-refname "FW_INCOMING_WAN_DMZ.$N.FROM_IP" fws_blocked-nets
N=$((N+1))
gc --silent --goto FW_INCOMING_WAN_DMZ --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT 0 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'web-in: published web servers'
gc --silent --set-refname "FW_INCOMING_WAN_DMZ.$N.IN_IP" fws_web-in_dst
gc --silent --set-refname "FW_INCOMING_WAN_DMZ.$N.IN_PORT" fws_web-in
N=$((N+1))
gc --silent --goto FW_INCOMING_WAN_DMZ --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT 25 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT mail-in
gc --silent --set-refname "FW_INCOMING_WAN_DMZ.$N.IN_IP" fws_mail-server
N=$((N+1))

# FW_INCOMING_DMZ_LAN
N=$(rows FW_INCOMING_DMZ_LAN)
gc --silent --goto FW_INCOMING_DMZ_LAN --add-row --set .PROTO udp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 10.10.0.60 --set .IN_PORT 514 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT dmz-syslog
N=$((N+1))

# FW_OUTGOING_LANDMZ
N=$(rows FW_OUTGOING_LANDMZ)
gc --silent --goto FW_OUTGOING_LANDMZ --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT 0 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT office-dmz
gc --silent --set-refname "FW_OUTGOING_LANDMZ.$N.FROM_IP" fws_office-lan
gc --silent --set-refname "FW_OUTGOING_LANDMZ.$N.IN_IP" fws_dmz-servers
gc --silent --set-refname "FW_OUTGOING_LANDMZ.$N.IN_PORT" fws_office-dmz
N=$((N+1))
gc --silent --goto FW_OUTGOING_LANDMZ --add-row --set .PROTO icmp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT ping-dmz
N=$((N+1))

# FW_1TO1_NAT
N=$(rows FW_1TO1_NAT)
gc --silent --goto FW_1TO1_NAT --add-row --set .LOCAL_NET 10.20.0.25 --set .REMOTE_NET 203.0.113.6 --set .MASK 32 --set .ENABLE_ARP yes --set .COMMENT 'nat-server-mail: nat server mail 2 global 203.0.113.6 inside 10.20.0.25'
N=$((N+1))

# FW_NAT
N=$(rows FW_NAT)
gc --goto FW_NAT --add-row --set .EXT_IF ext1 --set .IN_IP 10.30.0.0/24 --set .COMMENT lab-easy-ip
N=$((N+1))

if [ -z "$DRY_RUN" ]; then
  for v in FW_INCOMING_GLOBAL FW_OUTGOING_GLOBAL; do
    g=$(gaiconfig --get "$v" 2>/dev/null || true)
    [ "$g" = rules ] || printf 'NOTE: %s is %s: the rows take effect only with "Use the firewall ruleset below" (rules)\n' "$v" "$g" >&2
  done
fi
echo 'Done. Check the tables in the web interface (Network Security >> Packet Filter, Network >> NAT).' >&2
